-- Patch for already-seeded environments only.
--
-- Syncs the livestock_livestock_location_section_03 section_ui_schema to the canonical definition in
-- g2p_register_sections.sql (the seed only INSERTs and never touches an
-- existing row).
--
-- Why: a shared Master Data (dev) keys its geo values by id (region-ET04)
-- and links a zone to its region by that id, so the Region -> Zone -> Woreda ->
-- Kebele dropdowns now cascade on level_value_id and write region_id / zone_id /
-- woreda_id / kebele_id. The names in region / zone / woreda / kebele are
-- filled from the ids on save (register_domain/services/admin_area_sync.py).
UPDATE "public"."g2p_register_sections"
SET "section_ui_schema" = '{"section-required-for-submit": false, "section-title": "Location", "panels": [{"panels": [{"widgets": [{"widget": "select", "widget-id": "region", "widget-type": "input", "widget-label": "Region", "widget-readonly": false, "widget-required": false, "widget-data-path": "997676d3-7008-59f9-b23e-613ad79bbb08.region_id", "widget-data-source": {"type": "api", "method": "POST", "service": "master-data", "endpoint": "geo-level-values", "params": {"level_id": "level-region"}, "labelKey": "level_value_mnemonic", "valueKey": "level_value_id"}}, {"widget": "select", "widget-id": "zone", "widget-type": "input", "widget-label": "Zone", "widget-readonly": false, "widget-required": false, "widget-data-path": "997676d3-7008-59f9-b23e-613ad79bbb08.zone_id", "widget-data-source": {"type": "api", "method": "POST", "service": "master-data", "endpoint": "geo-level-values", "params": {"level_id": "level-zone"}, "labelKey": "level_value_mnemonic", "valueKey": "level_value_id", "dependsOn": "997676d3-7008-59f9-b23e-613ad79bbb08.region_id"}, "widget-cascade": {"listenTo": ["region"], "onEvent": "widget:change", "clearOnChange": true, "reloadOnChange": true}}], "panel-id": "vertical_panel_ls_livestock_location_1", "panel-orientation": "vertical"}, {"widgets": [{"widget": "select", "widget-id": "woreda", "widget-type": "input", "widget-label": "Woreda", "widget-readonly": false, "widget-required": false, "widget-data-path": "997676d3-7008-59f9-b23e-613ad79bbb08.woreda_id", "widget-data-source": {"type": "api", "method": "POST", "service": "master-data", "endpoint": "geo-level-values", "params": {"level_id": "level-woreda"}, "labelKey": "level_value_mnemonic", "valueKey": "level_value_id", "dependsOn": "997676d3-7008-59f9-b23e-613ad79bbb08.zone_id"}, "widget-cascade": {"listenTo": ["zone"], "onEvent": "widget:change", "clearOnChange": true, "reloadOnChange": true}}, {"widget": "select", "widget-id": "kebele", "widget-type": "input", "widget-label": "Kebele", "widget-readonly": false, "widget-required": false, "widget-data-path": "997676d3-7008-59f9-b23e-613ad79bbb08.kebele_id", "widget-data-source": {"type": "api", "method": "POST", "service": "master-data", "endpoint": "geo-level-values", "params": {"level_id": "level-kebele"}, "labelKey": "level_value_mnemonic", "valueKey": "level_value_id", "dependsOn": "997676d3-7008-59f9-b23e-613ad79bbb08.woreda_id"}, "widget-cascade": {"listenTo": ["woreda"], "onEvent": "widget:change", "clearOnChange": true, "reloadOnChange": true}}], "panel-id": "vertical_panel_ls_livestock_location_2", "panel-orientation": "vertical"}], "panel-id": "horizontal_panel_ls_livestock_location", "panel-orientation": "horizontal"}]}'::jsonb
WHERE "section_id" = 'livestock_livestock_location_section_03';
